using System.Text.Json;
using Arcoll.WinUI3.Services;
using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using Microsoft.Web.WebView2.Core;
namespace Arcoll.WinUI3.Pages;
/// <summary>Component workspace; one collector flight; changing cadence cancels the previous generation.</summary>
public sealed class ServerPage:UserControl
{
 private const string Origin="https://server.tidigital.local/";
 private readonly WebView2 _web=new(){HorizontalAlignment=HorizontalAlignment.Stretch,VerticalAlignment=VerticalAlignment.Stretch};
 private readonly PerformanceCollector _collector=new();private bool _ready,_loading,_active;private CancellationTokenSource? _session;private Task _sampling=Task.CompletedTask;private int _seconds=1,_generation;private int? _devices;private DateTimeOffset? _discovered;private PerformanceSnapshot? _last;private Palette _palette=new();
 public ServerPage(TelemetryHub hub,Func<string> status){Content=_web;Loaded+=async(_,_)=>{_active=true;await InitializeAsync();Restart();};Unloaded+=(_,_)=>{_active=false;_generation++;_session?.Cancel();};}
 public void ApplyPalette(Palette p){_palette=p;Publish();}
 private async Task InitializeAsync(){if(_ready||_loading)return;_loading=true;try{var profile=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"TI-Digital","PerformanceWebView");Directory.CreateDirectory(profile);var env=await CoreWebView2Environment.CreateWithOptionsAsync(null,profile,null);await _web.EnsureCoreWebView2Async(env);var core=_web.CoreWebView2;core.Settings.AreDevToolsEnabled=false;core.Settings.AreDefaultContextMenusEnabled=false;core.Settings.AreHostObjectsAllowed=false;core.SetVirtualHostNameToFolderMapping("server.tidigital.local",Path.Combine(AppContext.BaseDirectory,"Assets","hybrid","dashboard"),CoreWebView2HostResourceAccessKind.DenyCors);core.NavigationStarting+=(_,e)=>{if(!e.Uri.StartsWith(Origin,StringComparison.OrdinalIgnoreCase))e.Cancel=true;};core.NewWindowRequested+=(_,e)=>e.Handled=true;
 core.WebMessageReceived+=(_,e)=>{if(!e.Source.StartsWith(Origin,StringComparison.OrdinalIgnoreCase))return;try{using var doc=JsonDocument.Parse(e.WebMessageAsJson);var root=doc.RootElement;if(!root.TryGetProperty("action",out var action))return;if(action.GetString()=="ready"){_ready=true;Publish();}else if(action.GetString()=="cadence"&&root.TryGetProperty("seconds",out var s)&&s.TryGetInt32(out var seconds)&&PerformanceRules.IsCadence(seconds)){_seconds=seconds;Restart();Publish();}}catch(JsonException){}};_web.Source=new Uri(Origin+"server.html");}
 catch(Exception e){Content=Ui.Label("Monitor de componentes indisponível: "+e.Message,_palette.Text,14,wrap:true);}finally{_loading=false;}}
 private void Restart(){var generation=++_generation;_session?.Cancel();if(!_active||_seconds==0)return;var tokenSource=_session=new CancellationTokenSource();var previous=_sampling;_sampling=RunAsync(previous,generation,_seconds,tokenSource.Token);}
 private async Task RunAsync(Task previous,int generation,int seconds,CancellationToken ct){try{await previous;ct.ThrowIfCancellationRequested();if(generation!=_generation)return;_collector.ResetSampling();using var discoveryCancel=CancellationTokenSource.CreateLinkedTokenSource(ct);var scan=Task.Run(()=>DiscoverAsync(seconds,discoveryCancel.Token),discoveryCancel.Token);try{while(!ct.IsCancellationRequested){var watch=System.Diagnostics.Stopwatch.StartNew();var snapshot=await Task.Run(()=>_collector.SampleAsync(seconds,_devices,_discovered,ct),ct);ct.ThrowIfCancellationRequested();if(generation!=_generation)return;_last=snapshot;DispatcherQueue.TryEnqueue(()=>{if(generation==_generation&&_active)Publish();});var remaining=TimeSpan.FromSeconds(seconds)-watch.Elapsed;if(remaining>TimeSpan.Zero)await Task.Delay(remaining,ct);else await Task.Delay(50,ct);}}finally{discoveryCancel.Cancel();try{await scan;}catch(OperationCanceledException){}}}
 catch(OperationCanceledException){}catch(Exception e){DispatcherQueue.TryEnqueue(()=>{if(generation==_generation)Post(new{type="performance-error",message=e.Message});});}}
 private async Task DiscoverAsync(int seconds,CancellationToken ct){while(!ct.IsCancellationRequested){try{var found=await NetworkEngine.ScanAsync(null,true,ct);ct.ThrowIfCancellationRequested();_devices=found.Count;_discovered=DateTimeOffset.UtcNow;}catch(OperationCanceledException){return;}catch(Exception e){RuntimeLog.Write("Descoberta no Servidor: "+e.GetType().Name);}try{await Task.Delay(TimeSpan.FromSeconds(Math.Max(5,seconds)),ct);}catch(OperationCanceledException){return;}}}
 private void Publish(){if(!_ready)return;Post(new{type="performance",seconds=_seconds,snapshot=_last});}
 private void Post(object value){if(!_ready)return;try{_web.CoreWebView2.PostWebMessageAsJson(JsonSerializer.Serialize(value,new JsonSerializerOptions{PropertyNamingPolicy=JsonNamingPolicy.CamelCase}));}catch(InvalidOperationException){}}
}
